mapper.select:
/* selectJoinApplicationList */ select ja.application_id ,ja.guild_id ,g.guild_name ,ja.user_id ,tu.user_nm as user_name ,ja.status ,ja.message ,ja.reject_reason ,ja.crt_date from GUILD_JOIN_APPLICATION ja left outer join GUILD g on ja.guild_id = g.guild_id left outer join SYS_USER tu on ja.user_id = tu.user_id where 1=1
and ja.guild_id = CAST(#{guild_id} AS BIGINT)
and ja.status = #{status}
order by ja.crt_date desc

mapper.insert:
/* insertJoinApplication */
insert into GUILD_JOIN_APPLICATION (
	guild_id
	,user_id
	,status
	,message
	,crt_user_id
	,crt_date
	,upt_user_id
	,upt_date
) values (
	CAST(#{guild_id} AS BIGINT)
	,#{sess_user_id}
	,'PENDING'
	,#{message}
	,#{sess_user_id}
	,CURRENT_TIMESTAMP
	,#{sess_user_id}
	,CURRENT_TIMESTAMP
)

mapper.update:
/* updateJoinApplicationStatus */
update GUILD_JOIN_APPLICATION set
	status = #{status}
	,process_date = CURRENT_TIMESTAMP
	,process_user_id = #{process_user_id}

	,reject_reason = #{reject_reason}

	,upt_user_id = #{process_user_id}
	,upt_date = CURRENT_TIMESTAMP
where application_id = CAST(#{application_id} AS BIGINT)

/* cancelMyPendingJoinApplication */
update GUILD_JOIN_APPLICATION set
	status = 'CANCELLED'
	,process_date = CURRENT_TIMESTAMP
	,process_user_id = #{sess_user_id}
	,upt_user_id = #{sess_user_id}
	,upt_date = CURRENT_TIMESTAMP
where user_id = #{sess_user_id}
  and status = 'PENDING'
